starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "secret_name" {
  description = "Input variable secret_name."
  type        = string
  default     = "app/db"
}

variable "db_engine" {
  description = "Input variable db_engine."
  type        = string
  default     = "postgres"
}

variable "db_name" {
  description = "Input variable db_name."
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Input variable db_username."
  type        = string
  default     = "appuser"
}

variable "db_password" {
  description = "Input variable db_password."
  type        = string
}

variable "project_name" {
  description = "Input variable project_name."
  type        = string
  default     = "terraform-practice"
}

variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_secretsmanager_secret" "this" {
  name = "app-secret"
}

resource "aws_db_instance" "this" {
  # TODO - Complete the aws_db_instance resource.
  # Add the arguments and nested blocks required for aws_db_instance.
}

starter.outputs.tf:
output "secret_arn" {
  value = aws_secretsmanager_secret.this.arn
}

output "db_endpoint" {
  value = aws_db_instance.this.id
}
